/// Turkish provinces (by licence plate code) and their districts.
/// Profiles store [Province.code] and the district name.
class Province {
  const Province(this.code, this.name, this.districts, {this.localName, this.localDistricts});

  final int code;
  final String name;
  final List<String> districts;

  /// Name in the country's own script (e.g. Cyrillic), if different.
  final String? localName;
  final Map<String, String>? localDistricts;
}

const _trAlphabet = 'abcçdefgğhıijklmnoöprsştuüvyz';

String _trLower(String s) => s.replaceAll('I', 'ı').replaceAll('İ', 'i').toLowerCase();

/// Orders strings by the Turkish alphabet (ç after c, ı before i, etc.).
int compareTurkish(String a, String b) {
  final x = _trLower(a), y = _trLower(b);
  for (var i = 0; i < x.length && i < y.length; i++) {
    final cx = _trAlphabet.indexOf(x[i]), cy = _trAlphabet.indexOf(y[i]);
    final diff = (cx < 0 ? x.codeUnitAt(i) + 100 : cx) - (cy < 0 ? y.codeUnitAt(i) + 100 : cy);
    if (diff != 0) return diff;
  }
  return x.length - y.length;
}

